_elementor_page_settings.custom_css:
html,
body{
width:100%;
overflow-x:hidden;
}

html::before{
    content:"";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: radial-gradient(at 20% 80%, #fff 1px, transparent 0px);
    background-size: 3px 3px;
    pointer-events: none;
    z-index: 2;
    opacity: 0.04;
    mix-blend-mode: plus-lighter;
}

.rx {
  /* Gradiente de texto */
  background: radial-gradient(circle, #F0C26C 53%, #D8AF61 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;

  font-style: italic !important;

  /* Brilho dourado ao redor */
  text-shadow:
    0 0 4px rgba(240, 194, 108, 0.1),
    0 0 8px rgba(216, 175, 97, 0.2);
}


.rx2 {
  color: #FBC426 !important;
  /* Ou, se quiser gradiente de texto: */
  background: radial-gradient(circle, #EDBF72 53%, #EDBF72 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
